-- ---------------------------------------------------------------------------
-- Bug history (append-only ledger). CREATED events derived from the bugs above.
-- ---------------------------------------------------------------------------
INSERT INTO bug_history (bug_id, actor_id, event_type, field_name, old_value, new_value, created_at)
SELECT id, reporter_id, 'CREATED', 'title', NULL, title, created_at
FROM bugs;

